import '@servicenow/sdk/global'
import { Flow, wfa, action, trigger } from '@servicenow/sdk/automation'

// Simple forEach test - verify data pills get UUID prefix
Flow(
    {
        $id: Now.ID['foreach_datapill_simple_test'],
        name: 'ForEach Data Pill Simple Test',
        description: 'Test that forEach item data pills are replaced with UUID prefixes',
    },
    wfa.trigger(
        trigger.record.created,
        { $id: Now.ID['foreach_simple_trigger'] },
        {
            table: 'problem',
            condition: '',
            run_on_extended: 'false',
            run_flow_in: 'background',
            run_when_user_list: [],
            run_when_setting: 'both',
            run_when_user_setting: 'any',
        }
    ),
    (_params) => {
        const problems = wfa.action(
            action.core.lookUpRecords,
            {
                $id: Now.ID['lookup_problems'],
                annotation: 'Find problem records',
            },
            {
                table: 'problem',
                conditions: 'active=true',
            }
        )

        wfa.flowLogic.forEach(
            wfa.dataPill(problems.Records, 'array.object'),
            { $id: Now.ID['foreach_problems'], annotation: 'Iterate each problem' },
            (item) => {
                wfa.action(
                    action.core.log,
                    {
                        $id: Now.ID['log_problem'],
                        annotation: 'Log problem info',
                    },
                    {
                        log_level: 'info',
                        log_message: `Problem: ${wfa.dataPill(item.number, 'string')}, Group: ${wfa.dataPill(item.assignment_group, 'reference')}`,
                    }
                )
            }
        )
    }
)
